{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.tekkitake_returns_consolidated as select a.order_id as reference_code ,concat(a.order_id,\'-\',a.product_id) as saleorderitemcode ,a.order_id ,upper(a.order_status) as order_status ,cast(a.order_timestamp as date) as order_date ,cast(DELIVERED_DATE as datetime) as Delivered_Date ,\'AMAZON\' AS marketplace ,\'AMAZON\' AS marketing_CHANNEL ,\'AMAZON\' AS SOURCE ,a.product_name ,a.sku ,a.product_category ,a.product_sub_category ,a.quantity as order_quantity ,a.city ,a.state ,ufi.pincode ,ufi.courier as shipping_courier ,ufi.awb ,a.name as customer_name ,coalesce(ufi.email,a.email) as customer_email ,cast(null as string) as return_request_number ,cast(ar.return_requested_at as datetime) as return_request_date ,cast(ar.return_delivery_date as datetime) as return_date ,ar.return_approval_status as return_approval_status ,ar.return_request_type as return_request_type ,ar.return_request_type as return_type ,coalesce((case when ar.return_approval_status = \'Approved\' then 1 else null end),a.is_refund) as return_flag ,ar.return_quantity as TOTAL_RETURNED_QUANTITY ,ar.return_reason as return_reason ,ufi.Payment_mode ,a.TOTAL_SALES ,upper(ar.returned_product_name) as returned_product_name ,ar.merchant_SKU as returned_sku ,ar.refunded_amount as returned_product_price ,case when a.is_refund = 1 then a.tax else 0 end as TOTAL_RETURN_TAX ,null as TOTAL_RETURN_AMOUNT_EXCL_TAX ,concat(a.order_id,\'-\',a.product_id)as returned_item_saleorderitemcode ,case when lower(ar.return_reason) like \'%exchange%\' then ar.returned_product_name end as exchange_product_name ,case when lower(ar.return_reason) like \'%exchange%\' then ar.merchant_SKU end as exchange_sku ,cast(null as float64) as exchange_product_total_price ,cast(null as string) as exchange_status ,ufi.order_status as oms_order_status ,CASE WHEN a.pincode LIKE \'1%\' OR a.pincode LIKE \'2%\' THEN \'North Region\' WHEN a.pincode LIKE \'3%\' OR a.pincode LIKE \'4%\' THEN \'West Region\' WHEN a.pincode LIKE \'5%\' OR a.pincode LIKE \'6%\' THEN \'South Region\' WHEN a.pincode LIKE \'7%\' OR a.pincode LIKE \'8%\' THEN \'East Region\' ELSE NULL END AS region ,ar.refunded_amount as total_refund_amount from maplemonk.tekkitake_amazon_fact_items a left join maplemonk.tekkitake_amazon_returns_fact_items ar on ar.order_id = a.order_id and ar.merchant_sku = a.sku left join (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY shipping_last_update_date DESC) AS rw FROM tekkitake-wh.maplemonk.tekkitake_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE \'%amazon%\' ) ufi WHERE ufi.rw = 1 ) UFI ON cast(a.order_id as string) = cast(UFI.order_id as string) AND cast(a.product_id as string) = cast(UFI.PRODUCT_ID as string) UNION ALL select f.order_id as reference_code ,concat(f.order_id,\'-\',f.product_id) as saleorderitemcode ,f.order_id ,upper(f.order_item_status) as order_status ,cast(f.order_date as date) as order_date ,cast(DELIVERED_DATE as datetime) as Delivered_Date ,\'FLIPKART\' AS mfrketplace ,\'FLIPKART\' AS mfrketing_CHANNEL ,\'FLIPKART\' AS SOURCE ,f.product_name ,f.sku ,cast(null as string) product_category ,cast(null as string) product_sub_category ,f.quantity as order_quantity ,f.city ,f.state ,f.pincode ,ufi.courier as shipping_courier ,ufi.awb ,f.name as customer_name ,coalesce(ufi.email,f.email) as customer_email ,cast(null as string) as return_request_number ,cast(fr.return_approval_date as datetime) as return_request_date ,cast(fr.order_service_completion_date as datetime) as return_date ,case when fr.return_approval_date is not null then \'Aprroved\' end as return_approval_status ,CASE WHEN LOWER(fr.return_reason) IN (\'defective product\',\'quality issue\',\'quality issues\',\'damaged shipment obd\',\'damaged product\',\'dead on arrival\',\'size fit issues\',\'missing item\',\'color style issues\',\'item not as described\',\'accessory defective\',\'customer rejection\',\'rejected by customer\',\'shipment returned\',\'corresponding pickup rejected\') THEN \'Return\' WHEN LOWER(fr.return_reason) IN (\'order cancelled\',\'shield cancellation\',\'cancelled otp validated\',\'orc validated with customer\',\'attempts exhausted\',\'max ivr attempts exhausted\',\'validated by ivr whatsapp\',\'whatsapp\',\'not serviceable\',\'shipment eob ageing\',\'aged beyond limit\',\'shipment unattended\',\'orc occ\',\'uncontrollable factors\',\'osm\',\'other state misroute\',\'seller did not handover\',\'smart pickup check override\',\'cancelled by client over api\',\'rfrpromisebreached\',\'shipment rto completed\') THEN \'RTO\' WHEN LOWER(fr.return_reason) IN (\'return cancelled\') THEN \'Return Cancelled\' WHEN LOWER(fr.return_reason) IN (\'shipment lost\') THEN \'Lost\' ELSE \'Unmapped\' END as return_request_type ,CASE WHEN LOWER(fr.return_reason) IN (\'defective product\',\'quality issue\',\'quality issues\',\'damaged shipment obd\',\'damaged product\',\'dead on arrival\',\'size fit issues\',\'missing item\',\'color style issues\',\'item not as described\',\'accessory defective\',\'customer rejection\',\'rejected by customer\',\'shipment returned\',\'corresponding pickup rejected\') THEN \'Return\' WHEN LOWER(fr.return_reason) IN (\'order cancelled\',\'shield cancellation\',\'cancelled otp validated\',\'orc validated with customer\',\'attempts exhausted\',\'max ivr attempts exhausted\',\'validated by ivr whatsapp\',\'whatsapp\',\'not serviceable\',\'shipment eob ageing\',\'aged beyond limit\',\'shipment unattended\',\'orc occ\',\'uncontrollable factors\',\'osm\',\'other state misroute\',\'seller did not handover\',\'smart pickup check override\',\'cancelled by client over api\',\'rfrpromisebreached\',\'shipment rto completed\') THEN \'RTO\' WHEN LOWER(fr.return_reason) IN (\'return cancelled\') THEN \'Return Cancelled\' WHEN LOWER(fr.return_reason) IN (\'shipment lost\') THEN \'Lost\' ELSE \'Unmapped\' END as return_type ,(case when not(LOWER(fr.return_reason) IN (\'return cancelled\')) then 1 else null end) as return_flag ,fr.quantity as TOTAL_RETURNED_QUANTITY ,fr.return_reason as return_reason ,ufi.Payment_mode ,f.TOTAL_SALES ,upper(fr.product_name) as returned_product_name ,fr.SKU as returned_sku ,fr.TOTAL_SALES as returned_product_price ,case when f.is_refund = 1 then f.tax else 0 end as TOTAL_RETURN_TAX ,fr.TOTAL_SALES - fr.tax as TOTAL_RETURN_AMOUNT_EXCL_TAX ,concat(f.order_id,\'-\',f.product_id)as returned_item_saleorderitemcode ,case when lower(fr.return_reason) like \'%exchange%\' then fr.product_name end as exchange_product_name ,case when lower(fr.return_reason) like \'%exchange%\' then fr.SKU end as exchange_sku ,cast(null as float64) as exchange_product_total_price ,cast(null as string) as exchange_status ,ufi.order_status as oms_order_status ,CASE WHEN f.pincode LIKE \'1%\' OR f.pincode LIKE \'2%\' THEN \'North Region\' WHEN f.pincode LIKE \'3%\' OR f.pincode LIKE \'4%\' THEN \'West Region\' WHEN f.pincode LIKE \'5%\' OR f.pincode LIKE \'6%\' THEN \'South Region\' WHEN f.pincode LIKE \'7%\' OR f.pincode LIKE \'8%\' THEN \'East Region\' ELSE NULL END AS region ,fr.total_sales - fr.shipping_price as total_refund_amount from maplemonk.tekkitake_flipkart_fact_items f left join maplemonk.tekkitake_flipkart_fact_items fr on fr.order_id = f.order_id and fr.sku = f.sku and fr.line_item_id = f.line_item_id left join (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY shipping_last_update_date DESC) AS rw FROM maplemonk.tekkitake_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE \'%flipkart%\' ) ufi WHERE ufi.rw = 1 ) UFI ON cast(f.order_id as string) = cast(UFI.order_id as string) AND cast(f.product_id as string) = cast(UFI.PRODUCT_ID as string)",
                    "transaction": true
                }
            ) }}
